import java.util.*;

class Solution {
  public int earliestSecondToMarkIndices(int[] nums, int[] change) {
    int n = nums.length, m = change.length;
    if (n > m) return -1;
    long total = 0;
    for (int x : nums) total += x;
    int l = n, r = m;
    while (l < r) {
      int z = (l + r) >>> 1;
      if (ok(nums, change, z, total)) r = z;
      else l = z + 1;
    }
    return ok(nums, change, l, total) ? l : -1;
  }

  boolean ok(int[] a, int[] c, int t, long total) {
    int[] first = new int[a.length];
    Arrays.fill(first, -1);
    int[] v = c.clone();
    for (int i = 0; i < t; i++) {
      int x = v[i] - 1;
      if (first[x] < 0 && a[x] != 0) first[x] = i;
      else v[i] = -1;
    }
    PriorityQueue<Integer> pq = new PriorityQueue<>();
    for (int i = t - 1; i >= 0; i--)
      if (v[i] != -1) {
        pq.add(a[v[i] - 1]);
        if (pq.size() > t - i - pq.size()) pq.poll();
      }
    long s = 0;
    for (int x : pq) s += x;
    return s + t - a.length - pq.size() >= total;
  }
}
